create table public.connections (
    "name" text not null primary key,
    "title" varchar(250) not null,
    "type" text not null check (type in ('CEX', 'DEX')),
    "logo" text null check (logo ~ '^https?://.*$'),
    "description" text null,
    "enabled" boolean not null default false,
    "created_at" timestamp with time zone not null default now()
);
create table public.portfolios (
    "id" bigint generated by default as identity not null,
    "connection_name" text not null references public.connections("name") on delete cascade,
    "user_id" uuid not null references auth.users on delete cascade default auth.uid(),
    "title" varchar(250) not null,
    "color" char(7) not null default '#000000' check (color ~ '^#[0-9A-Fa-f]{6}$'),
    "status" text not null check (status in ('disabled', 'active', 'inactive')),
    "created_at" timestamp with time zone not null default now()
);